let chapterObserver;
let lang=new URLSearchParams(location.search).get('lang')==='en'?'en':'ru';
const isCase=location.pathname.endsWith('finelo.html');
const t=(ru,en)=>lang==='ru'?ru:en;
const href=(page,hash='')=>`${page}?lang=${lang}${hash}`;
const external=(url,label)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
const screen=(name,ru,en)=>`<button class="screen" data-image="${name}" data-caption="${t(ru,en)}" aria-label="${t('Увеличить: ','Enlarge: ')+t(ru,en)}"><img src="assets/${name}.png" alt="${t(ru,en)}" loading="lazy" width="375" height="812"><span class="zoom-hint" aria-hidden="true">↗</span></button>`;
const img=(name,alt)=>`<img src="assets/${name}.png" alt="${alt}" width="375" height="812">`;
const flower=`<svg class="flower" viewBox="0 0 100 100" aria-hidden="true"><g fill="currentColor"><ellipse cx="50" cy="50" rx="14" ry="48"/><ellipse cx="50" cy="50" rx="14" ry="48" transform="rotate(60 50 50)"/><ellipse cx="50" cy="50" rx="14" ry="48" transform="rotate(120 50 50)"/></g><circle cx="50" cy="50" r="10" fill="#faf9f6"/></svg>`;
function header(){return `<a class="skip" href="#main">${t('К содержанию','Skip to content')}</a><div class="header-shell"><header class="header wrap"><a class="wordmark" href="${href('index.html')}" aria-label="${t('Люда Запевалова — главная','Lyudmila Zapevalova — home')}"><span class="avatar" aria-hidden="true">${t('ЛЗ','LZ')}</span><span class="brand-name">${t('Люда Запевалова','Lyudmila Zapevalova')}</span></a><nav class="nav" aria-label="${t('Основная навигация','Main navigation')}"><div class="nav-links"><a href="${href('index.html','#work')}">${t('Проекты','Projects')}</a><a href="${href('index.html','#about')}">${t('Обо мне','About')}</a><a href="#contact">${t('Связаться','Contact')}</a><a href="assets/Lyudmila-Zapevalova-CV.pdf" target="_blank">${t('Резюме','CV')}</a></div><div class="languages" aria-label="${t('Язык сайта','Site language')}"><button data-lang="ru" aria-pressed="${lang==='ru'}">RU</button><button data-lang="en" aria-pressed="${lang==='en'}">EN</button></div></nav></header></div>`}
function footer(){return `<footer class="footer" id="contact"><div class="wrap"><div class="footer-main"><div><h2>${t('Открыта к новым<br>проектам и сотрудничеству.','Open to new projects<br>and collaboration.')}</h2><div class="contact-links"><a href="mailto:l.zapevalova@gmail.com">Email ↗</a>${external('https://t.me/l_zapevalova','Telegram')}<a href="assets/Lyudmila-Zapevalova-CV.pdf" target="_blank">${t('Резюме','CV')} ↗</a></div></div><a class="text-link" href="#top">${t('Наверх','Back to top')} ↑</a></div><div class="footer-meta"><span>© 2026 ${t('Люда Запевалова','Lyudmila Zapevalova')}</span><span>${t('Алматы, Казахстан','Almaty, Kazakhstan')}</span></div></div></footer>`}
const works=[
['02','Иви','Ivi','Скачивание контента для просмотра офлайн','Download content to watch offline',null],
['03','Ozon','Ozon','Поиск и выбор товаров','Product discovery and shopping','https://www.behance.net/gallery/255222461/Ozon-Discovery-Experience-Mobile-E-commerce-Product'],
['04','Звук','Zvuk','Перенос музыки из других сервисов','Bring your music from other services','https://www.behance.net/gallery/255116613/Music-transfer-feature-for-Zvuk-streaming-app'],
['05','CinemaPark','CinemaPark','Редизайн сайта кинотеатра','Cinema website redesign','https://www.behance.net/gallery/244309843/redizajn-sajta-sinema-park-Website-redesign'],
['06','Plate Planner','Plate Planner','Планирование питания и покупок','Meal planning and grocery shopping','https://www.behance.net/gallery/253168279/Meal-Planning-Grocery-Shopping-UXUI-Case-Study']];
function workRow(w){return `<${w[5]?'a':'div'} class="work-row ${w[5]?'':'pending'}" ${w[5]?`href="${w[5]}" target="_blank" rel="noopener noreferrer"`:''}><span class="num">${w[0]}</span><h3>${t(w[1],w[2])}</h3><p>${t(w[3],w[4])}</p><span class="status">${t('Учебный проект','Study project')}<br>${w[5]?'Behance':t('Скоро в портфолио','Case study coming soon')}</span></${w[5]?'a':'div'}>`}
const skills=[['Figma','Figma'],['FigJam','FigJam'],['Notion','Notion'],['Miro','Miro'],['Pthwy','Pthwy'],['Principle','Principle'],['Прототипирование','Prototyping'],['Вайрфрейминг','Wireframing'],['Дизайн-системы','Design systems'],['UX-исследования','UX research'],['CustDev','CustDev'],['CJM','CJM'],['Мобильные интерфейсы','Mobile design'],['Веб-интерфейсы','Web design'],['Продуктовая аналитика','Product analytics'],['A/B-тестирование','A/B testing'],['Маркетинг','Marketing'],['Передача в разработку','Design handoff'],['Codex','Codex'],['Claude','Claude'],['Английский B2','English B2']];
function home(){return `<main id="main" class="wrap"><section class="hero"><div class="eyebrow"><span class="dot"></span>${t('ПРОДУКТОВЫЙ ДИЗАЙНЕР · АЛМАТЫ','PRODUCT DESIGNER · ALMATY')}</div><h1>${t('Привет, я Люда.<br>Проектирую интерфейсы,<br> которые <em>легко понять.</em>','Hi, I’m Lyuda.<br>I design interfaces<br> that <em>make sense.</em>')}</h1>${flower}<div class="hero-bottom"><p>${t('Проектирую мобильные и веб-продукты: от первых вопросов пользователям до запуска и работы с результатами.','I design mobile and web products, from asking the first questions to shipping and learning from the results.')}</p><a class="text-link" href="#work">${t('Смотреть проекты','Explore projects')} ↓</a></div></section><section id="work" aria-label="${t('Проекты','Projects')}"><a class="feature" href="${href('finelo.html')}"><div class="feature-copy"><div class="feature-tags"><span>B2C</span><span>EdTech</span><span>2026</span></div><h3>Finelo</h3><p class="feature-description">${t('Трейдинг и инвестиции:<br>от теории к практике','Trading and investing:<br>from theory to practice')}</p><p class="feature-platform">${t('Мобильное приложение и веб','Mobile app and web')}</p><p class="feature-scope">${t('Мой вклад — от исследований<br>до запуска и анализа результатов.','My work: from research<br>to launch and measuring results.')}</p></div><div class="feature-screens" aria-hidden="true">${img('pathway','')}${img('complete','')}${img('practice','')}</div></a><div class="other-projects">${works.slice(0,3).map(workRow).join('')}</div></section><section class="web-works"><div class="section-top"><h2>${t('Ещё немного веба','A little more web')}</h2><span>${t('Интерфейсы для большого экрана','Designing for larger screens')}</span></div>${works.slice(3).map(workRow).join('')}</section><section id="about" class="about"><div class="about-title"><h2>${t('Немного<br>обо мне','A little<br>about me')}</h2><span class="asterisk" aria-hidden="true">✳</span></div><div class="about-copy"><p>${t('Разбираюсь в задаче, задаю вопросы и проверяю гипотезы. Соединяю потребности людей, цели продукта и возможности разработки.','I get to the heart of a problem, ask questions and test hypotheses. I bring together people’s needs, product goals and engineering constraints.')}</p><p>${t('Внимательна к деталям: от текста на кнопке до состояний интерфейса. Беру ответственность за задачу и довожу решение до запуска вместе с командой.','I pay attention to details, from button copy to interface states. I take ownership of a task and work with the team to bring the solution to launch.')}</p><p>${t('В свободное время читаю, вяжу классные штуки, хожу в походы и катаюсь на горных лыжах. И да, я фанатка вселенной Гарри Поттера.','Outside work, I read, knit fun things, hike and ski. And yes, I’m a fan of the Harry Potter universe.')}</p><a class="text-link" href="assets/Lyudmila-Zapevalova-CV.pdf" target="_blank">${t('Подробнее в резюме','Read my CV')} ↗</a></div></section><section class="skills-section" id="skills"><div class="skills-heading"><h2>${t('Что я умею','What I bring')}</h2></div><ul class="skill-cloud">${skills.map(([ru,en],i)=>`<li class="skill-chip skill-${i%5}" style="--tilt:${i%2===0?'-2':'2'}deg;--delay:${i*25}ms">${t(ru,en)}</li>`).join('')}</ul></section></main>`}
function caption(title,desc){return `<figcaption class="media-caption"><h3>${title}</h3><p>${desc}</p></figcaption>`}
function intro(num,title,desc=''){return `<div class="chapter-intro"><div class="chapter-index">${num}</div><div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div></div>`}
function finelo(){return `<main id="main" class="wrap"><a class="back" href="${href('index.html','#work')}">← ${t('Все работы','All work')}</a><section class="case-head"><div class="case-heading"><div><h1>Finelo</h1><div class="case-tags"><span class="badge">B2C</span><span class="badge">EdTech</span><span class="badge">Mobile & Web</span></div></div><h2>${t('Учиться трейдингу<br>и инвестициям<br>через практику','Learning trading<br>and investing<br>through practice')}</h2></div><p class="intro">${t('Приложение с короткими уроками, практикой и игровыми механиками. Основная аудитория — пользователи из США.','An app that brings together short lessons, hands-on practice and game mechanics, primarily for a US audience.')}</p><div class="passport"><div><span class="label">${t('Компания','Company')}</span><p>Zimran</p></div><div><span class="label">${t('Моя роль','My role')}</span><p>Product Designer</p></div><div><span class="label">${t('Период','Timeline')}</span><p>${t('Февраль — июль 2026','February — July 2026')}</p></div></div><div class="team"><span class="label">${t('Команда продукта','Product team')}</span><p>${t('CEO, продакт, 4 продуктовых дизайнера, Rive-аниматор, 4 Learning Designers, 8 разработчиков и аналитик. Работала со всей командой.','CEO, product manager, 4 product designers, a Rive animator, 4 Learning Designers, 8 developers and an analyst. I worked closely with the whole team.')}</p></div><div class="case-external">${external('https://finelo.com',t('Сайт продукта','Product website'))}${external('https://apps.apple.com/si/app/finelo-master-trading/id6670422243','App Store')}</div></section><div class="case-cover" aria-label="${t('Экраны приложения Finelo','Finelo app screens')}">${img('pathway',t('Путь обучения','Learning path'))}${img('complete',t('Завершение урока','Lesson complete'))}${img('leaderboard',t('Лидерборд','Leaderboard'))}</div><nav class="chapter-nav" aria-label="${t('Разделы кейса','Case sections')}"><div class="inner">${[['product','Продукт','The product'],['contribution','Моя работа','My work'],['support','Поддержка','Support'],['webapp','Web → App','Web → App'],['upsells','Апселлы','Add-ons'],['research','Исследования','Research'],['system','Дизайн-система','Design system']].map(([id,ru,en])=>`<a href="#${id}">${t(ru,en)}</a>`).join('')}</div></nav>
<section class="chapter" id="product">${intro('01 / '+t('ПРОДУКТ','THE PRODUCT'),t('От первого урока<br>к практике','From the first lesson<br>to hands-on practice'))}<figure class="visual-block"><div class="screen-stage pathway-stage">${screen('pathway','Путь обучения на главном экране','Learning path on the home screen')}<div class="pathway-aside"><span class="big-number">01 →</span><p>${t('Тема за темой.<br>В своём темпе.','One topic at a time.<br>At your own pace.')}</p><div class="path-line"></div><span class="quiz-label">${t('Проверочный квиз ✓','Knowledge check ✓')}</span></div></div>${caption(t('Путь обучения','The learning path'),t('Пользователь последовательно изучает темы, а в конце каждой проходит проверочный квиз. Весь путь обучения виден на главном экране.','Users work through topics in order and take a quiz at the end of each one. The home screen shows the entire learning path.'))}</figure><figure class="visual-block"><div class="screen-stage mint">${screen('quiz','Задание в уроке','Lesson exercise')}${screen('practice','Покупка или продажа по тренду на графике','Buy or sell based on a chart trend')}${screen('feedback','Обратная связь после задания','Feedback after an exercise')}</div>${caption(t('Уроки и практика','Lessons and practice'),t('Короткие объяснения чередуются с заданиями: сопоставить варианты ответов или выбрать покупку либо продажу по тренду на графике. После каждого задания пользователь сразу получает обратную связь.','Short explanations alternate with exercises: matching answers or choosing to buy or sell based on a chart trend. Users get immediate feedback after each task.'))}</figure><figure class="visual-block"><div class="screen-stage peach">${screen('complete','Урок завершён','Lesson complete')}${screen('streak','Серия занятий','Learning streak')}${screen('leaderboard','Место в рейтинге','Leaderboard progress')}</div>${caption(t('Игровые механики','Game mechanics'),t('Награды за уроки, серии занятий и место в рейтинге помогают видеть прогресс и добавляют игровой интерес.','Lesson rewards, learning streaks and leaderboard progress bring a sense of achievement and play to the learning experience.'))}</figure><figure class="visual-block"><div class="screen-stage blue">${screen('simulator','Виртуальный симулятор','Virtual trading simulator')}${screen('mentor','AI-ментор','AI mentor')}</div>${caption(t('Инструменты для практики','Tools for practice'),t('Виртуальный симулятор, AI-ментор, анализатор графиков и другие инструменты помогают применять знания на практике. Некоторые доступны как дополнения к подписке.','A virtual simulator, AI mentor, chart analyzer and other tools help users put their knowledge into practice. Some are available as subscription add-ons.'))}</figure><p class="subline">${t('Эти экраны знакомят с продуктом. Ниже — задачи и интерфейсы, над которыми работала я.','These screens introduce the product. Below are the tasks and interfaces I worked on.')}</p></section>
<section class="chapter" id="contribution">${intro('02 / '+t('МОЯ РАБОТА','MY WORK'),t('От вопроса «почему?»<br>до работающего решения','From asking “why?”<br>to a working solution'),t('Работала над переходом в приложение, онбордингом, поддержкой, дополнительными покупками и другими сценариями. Вела задачи от исследования до запуска: готовила макеты, описывала поведение и анимацию, проверяла реализацию. Вместе с разработчиками запускала тесты, собирала дашборды и следила за результатами.','I worked on the transition to the app, onboarding, support, add-ons and other flows. I owned tasks from research to launch: designed screens, documented interactions and motion, and checked the implementation. I ran tests with developers, built dashboards and tracked the results.'))}<div class="contribution-grid"><figure class="visual-block"><div class="wide-stage"><button data-image="purchases" data-caption="${t('Покупки внутри приложения','In-app purchases')}" aria-label="${t('Увеличить экраны покупок','Enlarge purchase screens')}"><img src="assets/purchases.png" alt="${t('Выбор и покупка учебных материалов','Choosing and purchasing learning materials')}" loading="lazy"></button></div>${caption(t('Покупки внутри приложения','In-app purchases'),t('Выбор учебных материалов, покупка и доступ к ним.','Choosing learning materials, making a purchase and getting access.'))}</figure><figure class="visual-block"><div class="wide-stage" style="background:var(--lavender)"><button data-image="localization" data-caption="${t('Локализация и страницы в магазинах','Localization and store listings')}" aria-label="${t('Увеличить локализацию','Enlarge localized screens')}"><img src="assets/localization.png" alt="${t('Изображения для магазина приложений на арабском языке','Arabic app store screenshots')}" loading="lazy"></button></div>${caption(t('Локализация и стор-скрины','Localization and store listings'),t('Адаптация интерфейсов и изображений, в том числе для языков с письмом справа налево.','Adapting interfaces and store screenshots, including for right-to-left languages.'))}</figure></div><div class="own-welcome"><div><h3>${t('Первое знакомство<br>с приложением','A first introduction<br>to the app')}</h3><p>${t('Проектировала первый вход и экраны обновления приложения. Продумывала, что пользователь увидит и что сможет сделать дальше.','I designed first-time entry and app update screens, considering what users see and what they can do next.')}</p></div><div class="screen-stage yellow">${screen('welcome','Первый вход в приложение','First entry into the app')}</div></div></section>
<section class="chapter" id="support"><div class="task-number">03 / ${t('ПОДДЕРЖКА','SUPPORT')}</div><div class="task-heading"><h2>${t('Помощь, которую<br>легко найти','Help that’s<br>easy to find')}</h2><div><p>${t('Поддержку было трудно найти в настройках. Столкнувшись с проблемой, пользователь мог запросить возврат или оставить негативный отзыв, не обратившись за помощью.','Support was difficult to find in settings. When something went wrong, users could request a refund or leave a negative review without reaching out for help.')}</p><p>${t('Я сделала вход заметнее и разделила два пути: найти ответ в FAQ или сразу связаться с поддержкой. До формы обращения стало можно дойти без перехода через FAQ.','I made the entry point more visible and separated two options: look for an answer in the FAQ or contact support directly. Users could now reach the contact form without going through the FAQ.')}</p></div></div><div class="screen-stage mint">${screen('settings','Заметный вход в поддержку в настройках','Visible support entry in settings')}${screen('faq','Выбор между FAQ и обращением в поддержку','FAQ or direct contact with support')}</div><div class="result-strip"><div class="metric"><div class="value">${t('+4,5','+4.5')} <small>${t('п. п.','pp')}</small></div><p>${t('дошли до сценария поддержки<br>17,1% против 12,6%','reached the support flow<br>17.1% vs 12.6%')}</p></div><div class="metric"><div class="value">${t('−10,9%','−10.9%')}</div><p>${t('показатель отписок · Day 1','unsubscribe rate · Day 1')}</p></div><div class="metric"><div class="value">${t('−9,2%','−9.2%')}</div><p>${t('показатель отписок · Day 7','unsubscribe rate · Day 7')}</p></div><div class="metric"><div class="value">${t('−5,7%','−5.7%')}</div><p>${t('показатель отписок · Day 30','unsubscribe rate · Day 30')}</p></div></div><p class="note">${t('Результаты эксперимента с доступом к поддержке. Решение выпустили в продукт. Эта задача показала мне, что даже небольшие изменения интерфейса могут дать заметный результат.','Results of the support access experiment. The solution was released. This task showed me that even small interface changes can make a meaningful difference.')}</p><div class="next-step"><h3>${t('Позже — чат с поддержкой','Later: support chat')}</h3><p>${t('Я предложила переписку с CX-агентом в формате мессенджера. Для этого нужно было сократить время ответа до 3–5 минут. Чат удалось внедрить.','I suggested a messenger-style chat with a CX agent. This required reducing response time to 3–5 minutes. The chat was implemented.')}</p></div></section>
<section class="chapter" id="webapp"><div class="split-task"><div><div class="task-number">04 / WEB → APP</div><h2>${t('Продолжить обучение<br>в приложении','Continue learning<br>in the app')}</h2><p>${t('Пользователи 55+ реже переходили из веба в мобильное приложение. Я изучила воронку и решения конкурентов.','Users aged 55+ were less likely to move from the web to the mobile app. I analyzed the funnel and reviewed competitors’ approaches.')}</p><p>${t('Предложила понятный следующий шаг, простую инструкцию и возможность остаться в браузере.','I proposed a clear next step, simple instructions and the option to continue in the browser.')}</p><div class="outcome">${t('Активация приложения выросла.<br>Решение распространили на все возрастные группы.','App activation increased.<br>The solution was extended to all age groups.')}</div></div><div class="screen-stage blue">${screen('webapp','Приглашение перейти в приложение','Invitation to continue in the app')}</div></div></section>
<section class="chapter" id="upsells"><div class="task-number">05 / ${t('ДОПОЛНЕНИЯ К ПОДПИСКЕ','SUBSCRIPTION ADD-ONS')}</div><div class="task-heading"><h2>${t('Понятная покупка.<br>Сохранённая выручка.','A clearer purchase.<br>Revenue preserved.')}</h2><p>${t('Одновременно поступило много требований от комплаенса. Макеты были разрознены, часть экранов из продукта отсутствовала в Figma. Нужно было ясно показать, что дополнение оплачивается отдельно, и сохранить выручку от этих покупок.','Many compliance requirements arrived at once. Designs were scattered and some live screens were missing from Figma. We needed to make it clear that add-ons were separate purchases while preserving their revenue.')}</p></div><div class="upsell-layout"><div class="upsell-story"><p>${t('В продукте было четыре направления: учебные челленджи по трейдингу и инвестициям, а также направления с ИИ-инструментами. Например, ботами, которые помогали пользователям вырабатывать и применять свою стратегию. Набор дополнений зависел от направления.','The product had four tracks: trading and investing learning challenges, plus tracks with AI tools, such as bots that helped users develop and apply their own strategies. Each track offered different add-ons.')}</p><div class="large">15 <span>${t('локалей','locales')}</span></div><p>${t('Согласовать тексты, оформление и условия покупки.','Align wording, design and purchase terms.')}</p><h3>${t('Восстановить актуальную картину','Restore the current designs')}</h3><p>${t('Восстановила недостающие макеты и работала над переводами. Вместе с разработчиками проверяла, что после покупки пользователь получает нужные учебные материалы.','I rebuilt missing screens and worked on translations. With developers, I checked that each purchase delivered the right learning materials.')}</p><h3>${t('Уточнить тексты и экраны','Clarify the copy and screens')}</h3><p>${t('Переработала интерфейсы и UX-тексты по требованиям комплаенса. Вместе с разработчиком запускала тесты и следила за выручкой.','I revised the interfaces and UX copy to meet compliance requirements. I ran experiments with a developer and tracked revenue.')}</p><div class="outcome">${t('Требования комплаенса учтены, языковые версии согласованы. ARPU апселлов — выручка на пользователя — не снизился. Отдельные варианты показали рост.','Compliance requirements were met and language versions aligned. Add-on ARPU — revenue per user — was maintained. Some variants showed an increase.')}</div></div><figure class="long-stage">${screen('upsell','Итоговый экран дополнительного предложения','Final add-on offer screen')}<figcaption>${t('Один из итоговых экранов дополнительных предложений','One of the final add-on offer screens')}</figcaption></figure></div></section>
<section class="chapter" id="research"><div class="task-number">06 / ${t('ИССЛЕДОВАНИЯ','RESEARCH')}</div><div class="research"><div><h2>${t('Один ресерч.<br>Два направления работы.','One study.<br>Two directions.')}</h2><p>${t('Изначально искали новые маркетинговые каналы. Я самостоятельно подготовила и провела интервью с пользователями из США на английском, затем систематизировала результаты.','The original goal was to find new marketing channels. I independently prepared and conducted interviews in English with US users, then synthesized the findings.')}</p><p>${t('В интервью проявились и другие трудности: ожидания от рекламы не всегда совпадали с опытом в продукте.','The interviews also revealed other difficulties: expectations set by ads did not always match the experience in the product.')}</p></div><div class="research-results"><div class="research-result"><span>01</span><div><b>${t('Для маркетинга','For marketing')}</b><p>${t('Собрала выводы для поиска новых каналов привлечения.','Compiled findings to inform the search for new acquisition channels.')}</p></div></div><div class="research-result"><span>02</span><div><b>${t('Для продукта','For the product')}</b><p>${t('Составила список проблем из интервью и предложила гипотезы для каждой.','Created a list of problems uncovered in interviews and proposed hypotheses for each.')}</p></div></div></div></div></section>
<section class="chapter" id="system">${intro('07 / '+t('ДИЗАЙН-СИСТЕМА','DESIGN SYSTEM'),t('Продумать даже<br>состояние ожидания','Designing even<br>the waiting moment'),t('Подготовила скелетоны для основных разделов приложения. Добавила компоненты и цветовые токены в дизайн-систему, описала анимацию и правила использования для разработчиков.','I designed skeleton loading states for the main app sections, added components and color tokens to the design system, and documented motion and usage rules for developers.'))}<div class="screen-stage" style="justify-content:center"><div class="skeleton-frame"><img src="assets/skeleton.png" alt="${t('Состояние загрузки симулятора','Simulator loading state')}" loading="lazy" width="375" height="812"><div class="skeleton-pulse" aria-hidden="true"></div></div>${screen('simulator','Загруженный экран симулятора','Loaded simulator screen')}</div><div class="screen-pair-labels"><span>${t('Содержимое загружается','Loading content')}</span><span>${t('Экран готов','Ready to use')}</span></div><button class="motion-control" id="motion-toggle" aria-pressed="false">${t('Ⅱ Пауза анимации','Ⅱ Pause animation')}</button></section><div class="case-end"><div><h2>${t('Спасибо за внимание','Thanks for reading')}</h2><p>${t('Обсудим задачу или познакомимся поближе?','Have a question or a project to discuss?')}</p></div><a class="text-link" href="mailto:l.zapevalova@gmail.com">${t('Написать мне','Get in touch')} ↗</a></div></main>`}
function render(){if(chapterObserver)chapterObserver.disconnect();document.documentElement.lang=lang;document.title=isCase?`Finelo — ${t('Люда Запевалова','Lyudmila Zapevalova')}`:t('Люда Запевалова — Product Designer','Lyudmila Zapevalova — Product Designer');document.body.id='top';document.getElementById('app').innerHTML=header()+(isCase?finelo():home())+footer()+`<dialog class="lightbox" aria-label="${t('Просмотр макета','Design preview')}"><button class="close">${t('Закрыть','Close')} ×</button><img alt=""><p></p></dialog>`;bind();}
function bind(){document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>{const y=scrollY;lang=b.dataset.lang;const u=new URL(location.href);u.searchParams.set('lang',lang);history.replaceState({},'',u);render();scrollTo(0,y)}));const dlg=document.querySelector('dialog');document.querySelectorAll('[data-image]').forEach(b=>b.addEventListener('click',()=>{const im=dlg.querySelector('img');im.src=`assets/${b.dataset.image}.png`;im.alt=b.dataset.caption;dlg.querySelector('p').textContent=b.dataset.caption;dlg.classList.toggle('mobile-image',!['purchases','localization'].includes(b.dataset.image));dlg.showModal();document.body.style.overflow='hidden'}));dlg.querySelector('.close').addEventListener('click',()=>dlg.close());dlg.addEventListener('click',e=>{if(e.target===dlg){const r=dlg.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dlg.close()}});dlg.addEventListener('close',()=>document.body.style.overflow='');const motion=document.getElementById('motion-toggle');if(motion){const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let paused=reduced;function motionState(){document.getElementById('system').classList.toggle('paused',paused);motion.setAttribute('aria-pressed',String(paused));motion.textContent=paused?t('▷ Продолжить анимацию','▷ Play animation'):t('Ⅱ Пауза анимации','Ⅱ Pause animation')}motionState();if(reduced){motion.disabled=true;motion.textContent=t('Анимация отключена в настройках устройства','Animation disabled by your device preferences')}motion.addEventListener('click',()=>{paused=!paused;motionState()})}if(isCase){chapterObserver=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){document.querySelectorAll('.chapter-nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id))}})},{rootMargin:'-10% 0px -65% 0px'});document.querySelectorAll('.chapter').forEach(s=>chapterObserver.observe(s));}}
render();
